INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'assignment', 'n.', '/əˈsaɪnmənt/', '作业;任务', 'Mrs Peabody gave the class a writing assignment about summer vacation.', '皮博迪老师给全班布置了一篇关于暑假的写作作业。', 'School Life', 1, 0, 'senior', 'wordlist', 'required1', 'U1', 'a writing assignment', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'creative', 'adj.', '/kriˈeɪtɪv/', '有创造力的;有创意的', 'The teacher asked the students to be as creative as they could.', '老师要求学生们尽量发挥创意。', 'School Life', 2, 0, 'senior', 'wordlist', 'required1', 'U1', 'be creative', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'spelling', 'n.', '/ˈspelɪŋ/', '拼写;拼法', 'She told us to use proper spelling and grammar in the essay.', '她叫我们在作文里使用正确的拼写和语法。', 'School Life', 3, 0, 'senior', 'wordlist', 'required1', 'U1', 'proper spelling', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'grammar', 'n.', '/ˈɡræmə(r)/', '语法', 'Good grammar makes your writing easier to understand.', '良好的语法能让你的作文更易读懂。', 'School Life', 4, 0, 'senior', 'wordlist', 'required1', 'U1', 'spelling and grammar', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'blank', 'adj./n.', '/blæŋk/', '空白的;空白处', 'Jim stared at a blank sheet of paper for a long time.', '吉姆盯着一张白纸看了很久。', 'School Life', 5, 0, 'senior', 'wordlist', 'required1', 'U1', 'a blank sheet of paper', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'essay', 'n.', '/ˈeseɪ/', '文章;短文;作文', 'Almost everyone in class wrote an essay about the summer vacation.', '班里几乎每个人都写了一篇关于暑假的作文。', 'School Life', 6, 0, 'senior', 'wordlist', 'required1', 'U1', 'write an essay', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'imaginative', 'adj.', '/ɪˈmædʒɪnətɪv/', '富有想象力的', 'Jim was praised because his story was so imaginative.', '吉姆因为故事极富想象力而受到表扬。', 'School Life', 7, 0, 'senior', 'wordlist', 'required1', 'U1', 'be imaginative', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'courage', 'n.', '/ˈkʌrɪdʒ/', '勇气;胆量', 'He had the courage to write something quite different.', '他有勇气写出一些与众不同的东西。', 'School Life', 8, 0, 'senior', 'wordlist', 'required1', 'U1', 'have the courage to', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'harsh', 'adj.', '/hɑːʃ/', '严厉的;刺耳的', 'The teacher said she had some rather harsh words for the class.', '老师说她有些相当严厉的话要对全班讲。', 'School Life', 9, 0, 'senior', 'wordlist', 'required1', 'U1', 'harsh words', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'term', 'n.', '/tɜːm/', '学期;术语;期限', 'At the beginning of a new term, everyone felt a little nervous.', '新学期开始时,大家都有点紧张。', 'School Life', 10, 0, 'senior', 'wordlist', 'required1', 'U1', 'a new term', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'senior', 'adj.', '/ˈsiːniə(r)/', '高级的;年长的;高年级的', 'Anne was getting ready for her first day of senior high school.', '安妮正为高中第一天做准备。', 'School Life', 11, 0, 'senior', 'wordlist', 'required1', 'U1', 'senior high school', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'junior', 'adj.', '/ˈdʒuːniə(r)/', '初级的;较年幼的;低年级的', 'I remember the hopes I had in junior high school.', '我还记得自己在初中时怀有的希望。', 'School Life', 12, 0, 'senior', 'wordlist', 'required1', 'U1', 'junior high school', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'expectation', 'n.', '/ˌekspekˈteɪʃn/', '期望;预期', 'She had to face new classmates, new teachers and new expectations.', '她得面对新同学、新老师和新的期望。', 'School Life', 13, 0, 'senior', 'wordlist', 'required1', 'U1', 'new expectations', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'pressure', 'n.', '/ˈpreʃə(r)/', '压力', 'You may put yourself under pressure to make everything perfect.', '你可能会给自己施压,想让一切都完美。', 'School Life', 14, 0, 'senior', 'wordlist', 'required1', 'U1', 'under pressure', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'perfect', 'adj.', '/ˈpɜːfɪkt/', '完美的;理想的', 'There is no such thing as a perfect first day at school.', '完美的开学第一天是不存在的。', 'School Life', 15, 0, 'senior', 'wordlist', 'required1', 'U1', 'there is nothing perfect', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'comfort', 'n./v.', '/ˈkʌmfət/', '安慰;舒适;抚慰', 'I hope you find comfort in knowing you are not alone.', '我希望你能从“你并不孤单”中得到安慰。', 'School Life', 16, 0, 'senior', 'wordlist', 'required1', 'U1', 'find comfort in', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'sympathetic', 'adj.', '/ˌsɪmpəˈθetɪk/', '同情的;有同情心的', 'Being kind and sympathetic can help unhappy classmates feel better.', '友善而有同情心能帮助不开心的同学好受些。', 'School Life', 17, 0, 'senior', 'wordlist', 'required1', 'U1', 'kind and sympathetic', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'throughout', 'prep./adv.', '/θruːˈaʊt/', '自始至终;遍及', 'You will meet such people throughout your school life.', '在整个学校生活中你都会遇到这样的人。', 'School Life', 18, 0, 'senior', 'wordlist', 'required1', 'U1', 'throughout your life', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'adult', 'n./adj.', '/ˈædʌlt/', '成年人;成年的', 'You will find such people not only at school but throughout your adult life.', '你不仅在学校,在整个成年生活中也会遇到这样的人。', 'School Life', 19, 0, 'senior', 'wordlist', 'required1', 'U1', 'adult life', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'reflect', 'v.', '/rɪˈflekt/', '认真思考;反映;显示', 'When you reflect on an unkind comment, try not to take it to heart.', '当你思量一句不友善的评论时,尽量别往心里去。', 'School Life', 20, 0, 'senior', 'wordlist', 'required1', 'U1', 'reflect on', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'comment', 'n./v.', '/ˈkɒment/', '评论;议论', 'An unkind comment often says more about the giver than about you.', '一句不友善的评论往往更能说明说话人,而非你。', 'School Life', 21, 0, 'senior', 'wordlist', 'required1', 'U1', 'a nasty comment', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'behaviour', 'n.', '/bɪˈheɪvjə(r)/', '行为;举止', 'Such behaviour says more about the giver than the receiver.', '这样的行为更能说明施予者,而非承受者。', 'School Life', 22, 0, 'senior', 'wordlist', 'required1', 'U1', 'good behaviour', '美式拼 behavior;美音 /bɪˈheɪvjər/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'shortage', 'n.', '/ˈʃɔːtɪdʒ/', '不足;缺少', 'There will never be a shortage of kind people in your life.', '你的人生中善良的人永远不会短缺。', 'School Life', 23, 0, 'senior', 'wordlist', 'required1', 'U1', 'a shortage of', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'genuine', 'adj.', '/ˈdʒenjuɪn/', '真诚的;真心的;可信赖的', 'You will always meet genuine smiles and real friends at school.', '在学校你总会遇到真诚的笑容和真正的朋友。', 'School Life', 24, 0, 'senior', 'wordlist', 'required1', 'U1', 'a genuine smile', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'forward', 'adv.', '/ˈfɔːwəd/', '向前;前进', 'As you go forward into this new chapter, stay brave.', '当你迈入人生新篇章时,要保持勇敢。', 'School Life', 25, 0, 'senior', 'wordlist', 'required1', 'U1', 'go forward', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'chapter', 'n.', '/ˈtʃæptə(r)/', '(人生或历史的)时期,篇章;章节', 'Senior high school is a new chapter in your life.', '高中是你人生的新篇章。', 'School Life', 26, 0, 'senior', 'wordlist', 'required1', 'U1', 'a new chapter', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'limitation', 'n.', '/ˌlɪmɪˈteɪʃn/', '限制;局限;不足之处', 'We are most often held back by the limitations we put on ourselves.', '我们常常被自己给自己设下的局限所阻碍。', 'School Life', 27, 0, 'senior', 'wordlist', 'required1', 'U1', 'the limitations we put on ourselves', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'confusing', 'adj.', '/kənˈfjuːzɪŋ/', '难以理解的;令人困惑的', 'The new timetable was confusing during the first week of school.', '开学第一周新课表令人困惑。', 'School Life', 28, 0, 'senior', 'wordlist', 'required1', 'U1', 'a confusing rule', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'confusion', 'n.', '/kənˈfjuːʒn/', '困惑;混乱;不确定', 'There was some confusion about which classroom to go to.', '对于该去哪间教室,大家有些困惑。', 'School Life', 29, 0, 'senior', 'wordlist', 'required1', 'U1', 'in confusion', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'embarrassment', 'n.', '/ɪmˈbærəsmənt/', '窘迫;难堪', 'He felt some embarrassment when he answered the question wrongly.', '答错问题时他感到有些难堪。', 'School Life', 30, 0, 'senior', 'wordlist', 'required1', 'U1', 'feel embarrassment', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'immediate', 'adj.', '/ɪˈmiːdiət/', '立即的;立刻的', 'The teacher gave an immediate reply to my question.', '老师立刻回答了我的问题。', 'School Life', 31, 0, 'senior', 'wordlist', 'required1', 'U1', 'an immediate reply', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'torn', 'adj.', '/tɔːn/', '(在两者间)难以选择,左右为难', 'She was torn between joining the drama club and the music club.', '她在加入戏剧社还是音乐社之间难以抉择。', 'School Life', 32, 0, 'senior', 'wordlist', 'required1', 'U1', 'be torn between', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'pleasant', 'adj.', '/ˈpleznt/', '令人愉快的;可喜的', 'Getting an A on the story was a pleasant surprise for Jim.', '故事得了A对吉姆来说是个令人愉快的惊喜。', 'School Life', 33, 0, 'senior', 'wordlist', 'required1', 'U1', 'a pleasant surprise', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'deliver', 'v.', '/dɪˈlɪvə(r)/', '递送;传送;发表(演讲)', 'The head teacher will deliver a speech on the first day of term.', '班主任会在开学第一天发表讲话。', 'School Life', 34, 0, 'senior', 'wordlist', 'required1', 'U1', 'deliver a speech', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'adapt', 'v.', '/əˈdæpt/', '适应;使适合', 'I hope you have adapted well to your new school life.', '希望你已经很好地适应了新的学校生活。', 'School Life', 35, 0, 'senior', 'wordlist', 'required1', 'U1', 'adapt to', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'announce', 'v.', '/əˈnaʊns/', '宣布;通告', '“I think I''m going to like school here,” Anne announced.', '“我想我会喜欢这里的学校,”安妮宣布道。', 'School Life', 36, 0, 'senior', 'wordlist', 'required1', 'U1', 'announce the results', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'tolerate', 'v.', '/ˈtɒləreɪt/', '容忍;忍受', 'Marilla said she would not tolerate rude words about a teacher.', '玛丽拉说她不会容忍对老师不礼貌的话。', 'School Life', 37, 0, 'senior', 'wordlist', 'required1', 'U1', 'won''t tolerate', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'receiver', 'n.', '/rɪˈsiːvə(r)/', '接受者;收件人', 'Unkind words say more about the giver than the receiver.', '不友善的话更能说明说话者,而非听者。', 'School Life', 38, 0, 'senior', 'wordlist', 'required1', 'U1', 'the giver and the receiver', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'spirit', 'n.', '/ˈspɪrɪt/', '精神;情绪;心境', 'On the first day Anne came home in high spirits.', '第一天安妮兴高采烈地回到家。', 'School Life', 39, 0, 'senior', 'wordlist', 'required1', 'U1', 'in high spirits', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'concern', 'n./v.', '/kənˈsɜːn/', '担心;关心;关切', 'School rules were her biggest concern about senior high school.', '校规是她对高中最大的担忧。', 'School Life', 40, 0, 'senior', 'wordlist', 'required1', 'U1', 'my biggest concern', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'facility', 'n.', '/fəˈsɪləti/', '设施;设备', 'The new library has many modern facilities for students.', '新图书馆为学生配备了许多现代化设施。', 'School Life', 41, 0, 'senior', 'wordlist', 'required1', 'U1', 'modern facilities', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'convenient', 'adj.', '/kənˈviːniənt/', '方便的;便利的', 'The self-service borrowing system was very convenient.', '自助借书系统非常方便。', 'School Life', 42, 0, 'senior', 'wordlist', 'required1', 'U1', 'very convenient', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'attractive', 'adj.', '/əˈtræktɪv/', '有吸引力的;吸引人的', 'What makes the school library so attractive to students?', '是什么让学校图书馆对学生如此有吸引力?', 'School Life', 43, 0, 'senior', 'wordlist', 'required1', 'U1', 'an attractive place', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'relaxed', 'adj.', '/rɪˈlækst/', '放松的;轻松的', 'I felt totally relaxed while reading in the quiet library.', '在安静的图书馆里读书时我感到完全放松。', 'School Life', 44, 0, 'senior', 'wordlist', 'required1', 'U1', 'feel relaxed', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'conduct', 'v.', '/kənˈdʌkt/', '进行;实施;开展', 'The school newspaper is conducting an interview about first-week experiences.', '校报正在就开学第一周的经历进行采访。', 'School Life', 45, 0, 'senior', 'wordlist', 'required1', 'U1', 'conduct an interview', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'experience', 'n./v.', '/ɪkˈspɪəriəns/', '经历;体验;经验', 'New students felt happy to share their experiences about school.', '新生们乐于分享他们的校园经历。', 'School Life', 46, 0, 'senior', 'wordlist', 'required1', 'U1', 'share experiences', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'courageous', 'adj.', '/kəˈreɪdʒəs/', '勇敢的;有勇气的', 'Zilu was active and courageous in front of the class.', '子路在全班面前积极而勇敢。', 'School Life', 47, 0, 'senior', 'wordlist', 'required1', 'U1', 'be courageous', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'meaningful', 'adj.', '/ˈmiːnɪŋfl/', '有意义的;意味深长的', 'Confucius had many meaningful discussions with his students.', '孔子和学生有许多有意义的讨论。', 'School Life', 48, 0, 'senior', 'wordlist', 'required1', 'U1', 'a meaningful discussion', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s1u1.01', '①一般/进行/完成时态辨析(现在/过去)', 'A2', 10, '上外必修一 U1 — 看时间状语与语境选时态:now/every day→一般现在;at the moment/now→现在进行;yesterday/last term→一般过去;at this time yesterday→过去进行;already/by now/since→现在完成;by the time + 过去→过去完成。', 1, 'required1', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s1u1.02', '②过去将来时 would do / was(were) going to do', 'A2', 10, '上外必修一 U1 — 站在过去某时点看将来:said/hoped/thought + that 从句用 would do;表过去的打算用 was/were going to do。', 2, 'required1', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s1u1.03', '③时态呼应与语境选时态', 'A2', 10, '上外必修一 U1 — 主从句时态一致(主句过去→从句相应过去/过去将来);by the time / since / when 等连接词决定主从时态搭配。', 3, 'required1', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.01'), 'Every morning before class, Anne ____ her timetable to check which room to go to.', 'checks', 'is checking', 'checked', 'has checked', 'A', 'Every morning 表习惯性动作,用一般现在时。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.01'), 'Look! Jim ____ at a blank sheet of paper and can''t think of anything to write.', 'stares', 'is staring', 'stared', 'had stared', 'B', 'Look! 表此刻正在发生,用现在进行时。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.01'), 'Last term our English teacher ____ us a creative writing assignment about summer.', 'gives', 'is giving', 'gave', 'has given', 'C', 'Last term 是明确的过去时间,用一般过去时。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.01'), 'At this time yesterday evening, I ____ about my new school life in the quiet library.', 'thought', 'am thinking', 'have thought', 'was thinking', 'D', 'At this time yesterday 表过去某刻正在进行,用过去进行时。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.01'), 'It is the first time that I ____ a dorm with three other girls, so everything feels new.', 'have shared', 'shared', 'share', 'was sharing', 'A', 'It is the first time that 后从句用现在完成时。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.01'), 'By the time the teacher arrived, the students ____ their essays into the box.', 'put', 'had put', 'have put', 'were putting', 'B', 'By the time + 一般过去,主句动作更早完成,用过去完成时。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.01'), 'These days a lot of new students ____ hard to make friends in our class.', 'try', 'tried', 'are trying', 'had tried', 'C', 'These days 表现阶段持续动作,用现在进行时。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.01'), 'Many of my classmates ____ good friends of mine since the start of this term.', 'became', 'become', 'were becoming', 'have become', 'D', 'since the start of this term 表从过去持续到现在,用现在完成时。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.01'), 'When the bell rang, we ____ a science fiction story aloud in the English class.', 'were reading', 'read', 'have read', 'are reading', 'A', 'When the bell rang 时另一动作正在进行,用过去进行时。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.01'), 'Jim usually ____ his homework right after dinner, but tonight he can''t focus.', 'is doing', 'does', 'did', 'has done', 'B', 'usually 表习惯,用一般现在时。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.01'), 'I ____ already ____ in my assignment when the teacher reminded us of the deadline.', 'have; handed', 'did; hand', 'had; handed', 'was; handing', 'C', 'already + when 过去某点之前已完成,用过去完成时 had handed。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.01'), 'Listen! Someone ____ a welcome speech in the school hall right now.', 'delivers', 'delivered', 'has delivered', 'is delivering', 'D', 'Listen! ... right now 表此刻正在进行,用现在进行时。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.01'), 'So far this week I ____ three new friends in my new class.', 'have made', 'made', 'make', 'was making', 'A', 'So far 表到目前为止,用现在完成时。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.01'), 'Anne ____ home in high spirits on the first day of September last year.', 'comes', 'came', 'has come', 'was coming', 'B', 'on the first day ... last year 是过去具体时间,用一般过去时。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.01'), 'Our school library ____ early every weekday so that students can read before class.', 'is opening', 'opened', 'opens', 'has opened', 'C', 'every weekday 表规律性事实,用一般现在时。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.01'), 'While I ____ for the bus this morning, I met an old classmate from junior high.', 'waited', 'wait', 'have waited', 'was waiting', 'D', 'this morning 过去某段时间正在进行,While 引导,用过去进行时。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.01'), 'By the end of last term, Jim ____ greater progress in physics than ever before.', 'had made', 'made', 'has made', 'makes', 'A', 'By the end of last term 表过去某点之前完成,用过去完成时。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.01'), 'At present an increasing number of students ____ part in the school drama club.', 'take', 'are taking', 'took', 'had taken', 'B', 'At present 表现阶段正在进行,用现在进行时。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.01'), 'The first-year students ____ their way around the building before school started.', 'learn', 'have learned', 'learned', 'are learning', 'C', 'before school started 表过去,用一般过去时。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.01'), 'I ____ this story three times already, and I still find it moving.', 'read', 'am reading', 'had read', 'have read', 'D', 'three times already 表到现在的经历次数,用现在完成时。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.02'), 'Before the new term, Anne hoped that she ____ able to join a school drama club.', 'would be', 'will be', 'is', 'had been', 'A', 'hoped 站在过去看将来,从句用过去将来时 would be。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.02'), 'Maybe Jim thought he ____ Mrs Peabody for a chance to rewrite the assignment.', 'will beg', 'would beg', 'begs', 'had begged', 'B', 'thought 过去时点看将来的打算,用 would beg。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.02'), 'I was going to ____ you a message last night, but my phone ran out of power.', 'sending', 'sent', 'send', 'have sent', 'C', 'was going to + 动词原形 表过去的打算,send。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.02'), 'When she was in junior high, Lin expected that senior high ____ much harder.', 'will be', 'is', 'was being', 'would be', 'D', 'expected (过去) 看将来,用过去将来时 would be。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.02'), 'The teacher said she ____ pass back the writing the following day.', 'would', 'will', 'is going', 'had', 'A', 'said + the following day 过去看将来,用 would。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.02'), 'We were going to ____ the new library after class, but it was already closed.', 'visiting', 'visit', 'visited', 'have visited', 'B', 'were going to + 原形,表过去的计划,visit。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.02'), 'Jim promised that he ____ use proper spelling and grammar next time.', 'will', 'is going to', 'would', 'had', 'C', 'promised 过去看将来,用 would。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.02'), 'Anne believed that she ____ like the school here even before the first lesson.', 'will', 'is going to', 'had', 'would', 'D', 'believed (过去) 看将来,用过去将来时 would。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.02'), 'Mum knew her daughter ____ meet some unfriendly people in her adult life.', 'would', 'will', 'is going to', 'has', 'A', 'knew 过去看将来,用 would。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.02'), 'On the first day I felt sure that I ____ make new friends very soon.', 'will', 'would', 'am going to', 'had', 'B', 'felt sure (过去) 看将来,用 would。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.02'), 'The students were going to ____ their assignments in, but the teacher arrived late.', 'handing', 'handed', 'hand', 'have handed', 'C', 'were going to + 原形 表过去打算,hand。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.02'), 'Lizzie''s father said that growing up ____ help her face difficulties at school.', 'will', 'is going to', 'had', 'would', 'D', 'said 过去看将来,用 would。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.02'), 'I hoped that my new classmates ____ kind and friendly to me.', 'would be', 'will be', 'are', 'had been', 'A', 'hoped (过去) 看将来状态,用过去将来时 would be。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.02'), 'She told her friend that she ____ join the music club the next month.', 'will', 'would', 'is going to', 'has', 'B', 'told + the next month 过去看将来,用 would。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.02'), 'We were going to ____ a survey in class, but the lesson ended too soon.', 'doing', 'did', 'do', 'have done', 'C', 'were going to + 原形 表过去打算,do。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.02'), 'When he started senior high, Tom imagined that everything ____ be perfect.', 'will', 'is going to', 'had', 'would', 'D', 'imagined (过去) 看将来,用 would。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.02'), 'The new students were told that a training course ____ start before school.', 'would', 'will', 'is going to', 'had', 'A', 'were told 过去看将来,用 would。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.02'), 'Anne thought the master ____ be able to teach her something useful after all.', 'will', 'would', 'is going to', 'has', 'B', 'thought (过去) 看将来,用 would。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.02'), 'I was going to ____ part in the interview, but I felt too shy at the last minute.', 'taking', 'took', 'take', 'have taken', 'C', 'was going to + 原形 表过去打算,take。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.02'), 'Mrs Peabody hoped that one student ____ be brave enough to be imaginative.', 'will', 'is going to', 'had', 'would', 'D', 'hoped (过去) 看将来,用过去将来时 would。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.03'), 'Jim said that he ____ awake until 3 a.m. the night before, worrying about his grade.', 'had stayed', 'stayed', 'has stayed', 'would stay', 'A', '主句过去 said,从句更早的动作用过去完成时 had stayed。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.03'), 'By the time Anne got to class, the teacher ____ already graded all the essays.', 'has', 'had', 'would have', 'was', 'B', 'By the time + 过去,主句更早完成,用过去完成时 had。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.03'), 'Since I joined the drama club, I ____ much more confident in front of others.', 'felt', 'feel', 'have felt', 'had felt', 'C', 'Since + 过去时间点,主句用现在完成时 have felt。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.03'), 'When the teacher walked in, the students ____ quietly about the assignment.', 'talked', 'have talked', 'are talking', 'were talking', 'D', 'When + 过去,另一动作正在进行,用过去进行时 were talking。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.03'), 'Mum wrote that she ____ well what it was like to be a teenager.', 'remembered', 'remembers', 'would remember', 'has remembered', 'A', '主句过去 wrote,从句陈述当时状态,时态呼应用一般过去 remembered。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.03'), 'Anne announced that she ____ going to like school here.', 'is', 'was', 'had been', 'would', 'B', '主句过去 announced,从句呼应用 was going to,选 was。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.03'), 'By the end of the third year, Jim ____ great progress and made many friends.', 'made', 'has made', 'had made', 'would make', 'C', 'By the end of ... (过去) 之前完成,用过去完成时 had made。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.03'), 'I didn''t know my new desk-mate ____ from the same town as me until we talked.', 'comes', 'has come', 'would come', 'came', 'D', '主句过去 didn''t know,从句陈述当时事实,时态呼应用一般过去 came。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.03'), 'Since the new term began, our class ____ three interesting school activities.', 'has held', 'held', 'holds', 'had held', 'A', 'Since + 过去,主句用现在完成时 has held。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.03'), 'When Mrs Peabody started to comment on the essays, Jim ____ his eyes nervously.', 'closes', 'closed', 'has closed', 'would close', 'B', 'When + 过去,主句叙述过去动作,时态呼应用一般过去 closed。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.03'), 'The teacher explained that the library ____ a self-service borrowing system now.', 'has', 'would have', 'had', 'is having', 'C', '主句过去 explained,从句呼应用过去 had。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.03'), 'Before I entered senior high, I had wondered whether I ____ make any friends.', 'will', 'have', 'had', 'would', 'D', '主句过去 had wondered,从句站过去看将来,用过去将来时 would。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.03'), 'By the time the bell rang, we ____ the topic sentence for our paragraph.', 'had finished', 'finished', 'have finished', 'would finish', 'A', 'By the time + 过去,主句更早完成,用过去完成时 had finished。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.03'), 'She realised that her old fears about senior high ____ unnecessary after all.', 'are', 'had been', 'have been', 'would be', 'B', '主句过去 realised,从句指更早的状态,用过去完成时 had been。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.03'), 'Since Lizzie watched the video, she ____ less worried about senior high.', 'felt', 'feels', 'has felt', 'had felt', 'C', 'Since + 过去动作,主句用现在完成时 has felt。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.03'), 'When the new students arrived, some senior students ____ them around the building.', 'showed', 'have shown', 'show', 'were showing', 'D', 'When + 过去,另一动作正在进行,用过去进行时 were showing。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.03'), 'Marilla said she ____ not tolerate rude words about a teacher.', 'would', 'will', 'has', 'had', 'A', '主句过去 said,从句站过去看将来,用 would。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.03'), 'By last Friday our group ____ already chosen its interview topic.', 'has', 'had', 'would have', 'was', 'B', 'By last Friday 过去某点之前完成,用过去完成时 had。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.03'), 'I found that the library ____ quiet and comfortable when I first visited it.', 'is', 'has been', 'was', 'would be', 'C', '主句过去 found,从句呼应陈述当时状态,用一般过去 was。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required1' AND unit='U1' AND code='s1u1.03'), 'Since we became desk-mates, Zhang and I ____ many things about school together.', 'shared', 'share', 'had shared', 'have shared', 'D', 'Since + 过去,主句用现在完成时 have shared。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Different Writing Assignment', 'At the start of a new term, Mrs Peabody asked her class to write something about the summer vacation. She told the students to be creative, but to use proper spelling and grammar. That night Jim sat at home and stared at a blank sheet of paper. He did not want to write the same boring essay about a dog, a water park and two weeks of camp. So he wrote a short science fiction story instead. It was about a distant planet that had no summer and no vacations, where the people worked all day and wished they could rest. After he handed it in, Jim lay awake worrying that the teacher would think he had ignored the task. To his great surprise, he was the only student who got an A, because he had the courage to be imaginative. English was his favourite class, and now he felt proud of his own choice.', '记叙·一篇与众不同的作业', 155, '[{"q":"Why didn''t Jim write the usual essay about his summer vacation?","answer":"A","options":["He thought the usual topic was dull and wanted something fresh.","He had forgotten everything about his summer.","The teacher had banned writing about vacations.","He did not know how to spell the words."],"explanation":"原文 Jim 觉得老一套作文 boring 而想写不同的东西,转述其厌倦感。"},{"q":"What did Jim worry about after handing in his story?","answer":"B","options":["That he had lost his sheet of paper.","That the teacher might think he had not followed the task.","That his classmates would laugh at him.","That the planet in his story was too cold."],"explanation":"原文他担心老师认为他无视了作业要求,转述其顾虑。"},{"q":"Why did Jim finally get an A?","answer":"A","options":["He dared to use his imagination instead of playing safe.","He wrote the longest essay in class.","He copied the example the teacher gave.","He finished his work the fastest."],"explanation":"原文因为他有勇气富于想象,转述其得高分的原因。"}]'::jsonb, '[{"word":"assignment","cn":"作业"},{"word":"creative","cn":"有创意的"},{"word":"imaginative","cn":"富有想象力的"},{"word":"courage","cn":"勇气"}]'::jsonb, 2, 'required1', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Letter to My Daughter', 'Dear Daughter, as I watch you get ready for your first day of senior high school, there are a few things I want you to know. You may be putting yourself under pressure to make everything perfect, but there is no such thing as perfect. What matters most is believing that you are good enough, just as you are. Remember that you are not alone in this boat. Everyone else is facing a new school, new classmates and new pressures too. There may be some people who are not always friendly to you, and you will meet such people throughout your adult life. When someone makes a nasty comment, please remember that this kind of behaviour says more about the giver than about you. There will never be a shortage of kind people and genuine smiles in your life. As you go forward into this new chapter, I hope you will see that we are most often held back by the limits we put on ourselves. Love, Mum.', '书信·母亲给女儿的鼓励', 168, '[{"q":"What does the mother think about trying to be perfect on the first day?","answer":"B","options":["She insists her daughter must be perfect.","She believes perfection does not really exist and is not needed.","She wants her to give up the first day.","She says only teachers can be perfect."],"explanation":"原文母亲说世上没有完美这回事,重要的是相信自己足够好,转述其观点。"},{"q":"According to the mother, what does an unkind comment really show?","answer":"C","options":["That the receiver has done something wrong.","That the school rules are too strict.","More about the person who gives it than the one who receives it.","That the daughter should stay silent forever."],"explanation":"原文 behaviour says more about the giver,转述其含义。"},{"q":"What often holds people back, in the mother''s opinion?","answer":"D","options":["The number of friends they have.","The size of their new school.","The weather on the first day.","The limits they set on themselves rather than outside forces."],"explanation":"原文 held back by the limits we put on ourselves,转述其主旨。"}]'::jsonb, '[{"word":"pressure","cn":"压力"},{"word":"genuine","cn":"真诚的"},{"word":"shortage","cn":"缺少"},{"word":"limitation","cn":"局限"}]'::jsonb, 2, 'required1', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Library Everyone Loves', 'The school newspaper was conducting an interview about students'' first week at No. 1 Senior High School. Li Mei, the reporter, asked Zhang Yan and Zhao Shan what they liked best. Both of them spoke warmly about the school library. Zhao Shan said he loved the place the very first time he visited it. He explained that it took him only five minutes to borrow a book of short stories, because the self-service borrowing system was so convenient. The computer quickly helped him find what he wanted. Zhang Yan added that the environment was quiet and comfortable. The room was decorated with green plants and lovely desks and chairs, so she felt totally relaxed while reading there. The library also had a large collection of magazines and modern facilities. Li Mei smiled and agreed that it was a wonderful place to study. After the interview, the two students said they would visit the library again that afternoon.', '采访·人人喜爱的图书馆', 157, '[{"q":"Why was Zhao Shan able to borrow a book so quickly?","answer":"A","options":["The self-service system and computer made it fast and easy.","A teacher carried the book to him.","He had reserved the book a week before.","There was only one book in the library."],"explanation":"原文自助借书系统方便、电脑帮他快速找到,转述其原因。"},{"q":"What made Zhang Yan feel relaxed in the library?","answer":"B","options":["The loud music played all day.","Its quiet setting with plants and comfortable furniture.","The crowd of noisy students.","The lack of any books at all."],"explanation":"原文安静、有绿植和可爱桌椅让她放松,转述其感受。"},{"q":"What did the two students plan to do after the interview?","answer":"C","options":["Move to a different school.","Stop using the library forever.","Return to the library later the same day.","Write a complaint to the reporter."],"explanation":"原文他们说会当天下午再去图书馆,转述其计划。"}]'::jsonb, '[{"word":"conduct","cn":"进行"},{"word":"convenient","cn":"方便的"},{"word":"facility","cn":"设施"},{"word":"relaxed","cn":"放松的"}]'::jsonb, 2, 'required1', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'First Week Around the World', 'The first week of senior high school looks quite different from one culture to another. In South Korea and Japan, for example, it is a custom to welcome new students with a school entrance ceremony. The ceremony reminds students of their duties and responsibilities at the start of this new chapter. In some Japanese schools, skilled painters even draw cheerful welcome pictures on the blackboard so that the classroom feels warm and friendly. In the United States, most high schools offer a short training course before the term actually begins. During this course, new students learn their way around the building, meet some of their teachers and get to know a few fellow students. These different customs all share one purpose. They help young people feel less worried and more at home as they begin an important period of their lives. Whatever the culture, a kind welcome can make the first week far less frightening and much more pleasant.', '说明·各地开学第一周', 159, '[{"q":"What is the purpose of the entrance ceremony in South Korea and Japan?","answer":"D","options":["To test the students'' English grammar.","To choose the best painter in the school.","To decide who will be the class president.","To remind new students of their duties as they start school."],"explanation":"原文 ceremony 提醒学生职责与责任,转述其目的。"},{"q":"What do American high schools often do before the term starts?","answer":"A","options":["Run a short course to help newcomers find their way and meet people.","Send students straight home for a holiday.","Ask parents to teach the first lessons.","Cancel all classes for a month."],"explanation":"原文美国学校开学前办训练课程帮新生熟悉环境,转述其做法。"},{"q":"What do all these customs have in common?","answer":"B","options":["They force students to study harder than before.","They aim to make new students feel welcome and less anxious.","They only happen in very large cities.","They are designed to punish latecomers."],"explanation":"原文这些习俗都为让学生更安心、有归属感,转述其共同点。"}]'::jsonb, '[{"word":"throughout","cn":"遍及"},{"word":"chapter","cn":"篇章"},{"word":"pleasant","cn":"愉快的"}]'::jsonb, 2, 'required1', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'How to Have a Great First Year', 'Some senior students like to share tips to help first-year students settle in. Their first piece of advice is simple: try to meet new friends early. One student said she first met her best friend at a Year 7 camp, and they have stayed close ever since. The second tip is about good habits. New students are expected to be more independent, so it helps to start a regular study plan as soon as the term begins. You might set up a quiet corner at home where you can concentrate on your work without being disturbed. It is also useful to write a list of all your homework and tick off each task as you finish it. That way you always know when each assignment is due and can plan what to get done. Finally, never be afraid to ask your teachers for help when something is confusing. A little courage at the right moment can save you a lot of trouble later.', '建议·开学第一年小贴士', 163, '[{"q":"What is the senior students'' first piece of advice?","answer":"C","options":["To avoid talking to anyone at first.","To skip all the school camps.","To make new friends soon after starting school.","To change schools quickly."],"explanation":"原文第一条建议是早点结交新朋友,转述其内容。"},{"q":"Why is a regular study plan recommended?","answer":"D","options":["Because teachers will not give any homework.","Because the school has no timetable.","Because plans are only for exams.","Because newcomers are expected to manage their work more independently."],"explanation":"原文新生被期待更独立,所以应早定学习计划,转述其原因。"},{"q":"What should students do when something is confusing?","answer":"A","options":["Find the courage to ask a teacher for help.","Pretend everything is clear.","Give up the subject at once.","Wait until the end of the year."],"explanation":"原文遇困惑别怕向老师求助,转述其建议。"}]'::jsonb, '[{"word":"expectation","cn":"期望"},{"word":"confusing","cn":"令人困惑的"},{"word":"assignment","cn":"作业"}]'::jsonb, 2, 'required1', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Lesson from Confucius', 'For Confucius, China''s greatest teacher, learning was a powerful joint effort between teacher and student. He often had interesting and meaningful discussions with the young people who studied with him. Once Zilu asked the Master whether he should put a new idea into practice right away. Confucius replied that, since Zilu''s father and elder brothers were still alive, he should not act so immediately, but think of them first. Later Ran You asked exactly the same question. This time the Master answered yes, telling him to put the idea into action at once. The two students were puzzled by the different replies, but Confucius had a clear reason. The two boys had very different characters. Ran You was shy and slow, so the teacher encouraged him to go forward and be braver. Zilu, on the other hand, was active and courageous, so the teacher gently held him back. In this way Confucius taught each student in the way that suited him best.', '故事·孔子因材施教', 162, '[{"q":"Why did Confucius give the two students different answers?","answer":"B","options":["Because he had forgotten his first reply.","Because their characters were not the same and needed different guidance.","Because Ran You asked a harder question.","Because only one of them was his student."],"explanation":"原文两人性格不同,因材施教,转述其原因。"},{"q":"How did Confucius treat the shy and slow student, Ran You?","answer":"C","options":["He told him never to act at all.","He punished him for being slow.","He encouraged him to move forward and be braver.","He sent him away from class."],"explanation":"原文鼓励冉有前进更勇敢,转述其做法。"},{"q":"What does this story tell us about good teaching?","answer":"D","options":["Every student should be taught in exactly the same way.","Teachers should never explain their reasons.","Only brave students deserve attention.","A good teacher fits the advice to each learner''s nature."],"explanation":"原文孔子以最适合的方式教每个学生,转述其主旨。"}]'::jsonb, '[{"word":"meaningful","cn":"有意义的"},{"word":"immediate","cn":"立即的"},{"word":"courageous","cn":"勇敢的"}]'::jsonb, 2, 'required1', 'U1', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U1', 'My First Day at Senior High', 'On my very first day of senior high school, I woke up early and felt both excited and a little (1)____. I was afraid I might lose my way, so I checked the (2)____ many times to find the right room. When I walked into the classroom, a friendly girl smiled and (3)____ me to sit beside her. That small act of kindness helped me (4)____ much calmer at once. Our head teacher gave a short (5)____ about the new term and reminded us to work hard. During the morning, I tried to (6)____ the names of as many classmates as I could. At lunch I was still a bit (7)____, but a boy from my group started a chat and soon we were (8)____ together. By the end of the day, my early fears had nearly (9)____ away. I went home in high (10)____, sure that I was going to like this place.', 154, 2, '[{"q":"1","answer":"A","options":["nervous","lazy","angry","asleep"],"explanation":"开学第一天兴奋又紧张,nervous。"},{"q":"2","answer":"B","options":["weather","timetable","window","garden"],"explanation":"怕迷路所以查课表 timetable。"},{"q":"3","answer":"C","options":["refused","forced","invited","ignored"],"explanation":"友善地请我坐旁边,invited。"},{"q":"4","answer":"D","options":["buy","sell","throw","feel"],"explanation":"让我立刻感到平静,feel calmer。"},{"q":"5","answer":"A","options":["speech","meal","ticket","song"],"explanation":"班主任作简短讲话,speech。"},{"q":"6","answer":"B","options":["cook","remember","drive","paint"],"explanation":"尽量记住同学名字,remember。"},{"q":"7","answer":"C","options":["tall","rich","shy","hungry"],"explanation":"午餐时还有点害羞,shy。"},{"q":"8","answer":"D","options":["crying","sleeping","fighting","laughing"],"explanation":"聊起来后一起欢笑,laughing。"},{"q":"9","answer":"A","options":["gone","grown","frozen","fallen"],"explanation":"恐惧几乎消散,gone away。"},{"q":"10","answer":"B","options":["prices","spirits","rivers","boxes"],"explanation":"兴高采烈回家,in high spirits。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U1', 'Joining a School Club', 'When I was in junior high, I always hoped that I (1)____ join a drama club one day and perform on the stage. So in my first week of senior high, I decided to make that dream come (2)____. The teacher in charge welcomed me warmly and explained the club (3)____. At first I felt (4)____ when I tried to act in front of so many strangers. My voice shook and my face turned red with (5)____. But the older members were kind and (6)____ towards me, and they cheered me on. Little by little I learned to (7)____ on the lines instead of the audience. After a few weeks of (8)____ practice, I gave my first short performance, and people clapped for me. That moment was a pleasant (9)____ I will never forget. Now I tell new students that they should be brave enough to (10)____ something they truly love.', 151, 2, '[{"q":"1","answer":"C","options":["must","need","would","dare"],"explanation":"过去看将来的愿望,hoped that I would join。"},{"q":"2","answer":"D","options":["down","back","off","true"],"explanation":"让梦想成真,come true。"},{"q":"3","answer":"A","options":["rules","doors","walls","clothes"],"explanation":"讲解社团规则,club rules。"},{"q":"4","answer":"B","options":["proud","uneasy","sleepy","famous"],"explanation":"在陌生人面前表演感到不安,uneasy。"},{"q":"5","answer":"C","options":["joy","hunger","embarrassment","money"],"explanation":"脸红是因为难堪,embarrassment。"},{"q":"6","answer":"D","options":["lazy","rude","silent","sympathetic"],"explanation":"年长成员友善有同情心,sympathetic。"},{"q":"7","answer":"A","options":["focus","spend","live","depend"],"explanation":"学会专注于台词,focus on。"},{"q":"8","answer":"B","options":["free","hard","empty","loud"],"explanation":"几周的刻苦练习,hard practice。"},{"q":"9","answer":"C","options":["mistake","problem","surprise","danger"],"explanation":"那是个令人愉快的惊喜,pleasant surprise。"},{"q":"10","answer":"D","options":["drop","hide","lose","try"],"explanation":"鼓励尝试真正热爱的事,try something。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U1', 'Beating the First-Week Nerves', 'The first week of a new school can be confusing, and almost every student feels a little (1)____ at the start. The building is large, the faces are new, and the timetable seems (2)____ to follow. I remember standing in a busy corridor, not sure (3)____ classroom I should enter. But I soon learned that this feeling does not (4)____ very long. The best way to beat the nerves is to (5)____ a few simple plans. First, arrive a little early so that you have time to find your (6)____. Second, write down your homework and tick each task off as you (7)____ it. Third, do not be afraid to (8)____ a teacher for help when something is unclear. Most teachers are happy to give you (9)____ if you only dare to ask. By following these steps, you will feel more in (10)____ of your new life and far less worried each day.', 153, 2, '[{"q":"1","answer":"A","options":["lost","rich","asleep","angry"],"explanation":"开学第一周感到茫然,feel lost。"},{"q":"2","answer":"B","options":["easy","hard","cheap","soft"],"explanation":"课表似乎难以跟上,hard to follow。"},{"q":"3","answer":"C","options":["whose","why","which","how"],"explanation":"不确定该进哪间教室,which classroom。"},{"q":"4","answer":"D","options":["open","cook","drive","last"],"explanation":"这种感觉不会持续很久,last。"},{"q":"5","answer":"A","options":["make","break","sell","burn"],"explanation":"制定几个简单计划,make plans。"},{"q":"6","answer":"B","options":["money","way","lunch","bag"],"explanation":"有时间找路,find your way。"},{"q":"7","answer":"C","options":["start","lose","finish","forget"],"explanation":"完成一项就打钩,as you finish it。"},{"q":"8","answer":"D","options":["tell","leave","watch","ask"],"explanation":"向老师求助,ask a teacher。"},{"q":"9","answer":"A","options":["help","trouble","noise","homework"],"explanation":"老师乐意提供帮助,give you help。"},{"q":"10","answer":"B","options":["danger","control","fashion","secret"],"explanation":"更能掌控新生活,in control of。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U1', 'Fitting into a New Class', 'Moving into a brand-new class is one of the biggest (1)____ that senior high brings. At first you may know nobody, and that can feel (2)____. I was quite quiet during my first days, and I (3)____ that nobody would want to talk to me. Then one afternoon a classmate asked to (4)____ my notes, and we started chatting about our favourite subjects. From that day on, things slowly (5)____ better. I joined a study group, and we often helped one another (6)____ difficult problems. I learned that the best way to (7)____ friends is simply to be kind and open. When someone looked unhappy, I tried to be (8)____ and listen to them. Over time our class became more like a (9)____ family than a group of strangers. Looking back, I am glad I did not let my early shyness (10)____ me back from reaching out to others.', 149, 2, '[{"q":"1","answer":"C","options":["prizes","meals","changes","tickets"],"explanation":"进入新班级是巨大改变,biggest changes。"},{"q":"2","answer":"D","options":["funny","tasty","cheap","lonely"],"explanation":"谁也不认识会感到孤独,lonely。"},{"q":"3","answer":"A","options":["feared","hoped","promised","agreed"],"explanation":"我担心没人愿意跟我说话,feared。"},{"q":"4","answer":"B","options":["cook","borrow","throw","sell"],"explanation":"同学想借我的笔记,borrow my notes。"},{"q":"5","answer":"C","options":["kept","stayed","got","ran"],"explanation":"情况慢慢变好,got better。"},{"q":"6","answer":"D","options":["of","to","off","with"],"explanation":"帮彼此解决难题,help one another with。"},{"q":"7","answer":"A","options":["make","lose","break","miss"],"explanation":"交朋友,make friends。"},{"q":"8","answer":"B","options":["rude","kind","loud","lazy"],"explanation":"试着友善并倾听,be kind。"},{"q":"9","answer":"C","options":["cold","wide","warm","high"],"explanation":"班级更像温暖的家,warm family。"},{"q":"10","answer":"D","options":["give","take","put","hold"],"explanation":"不让羞怯妨碍我,hold me back。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U1', 'What School Friendship Means', 'Friendship is one of the most precious parts of school (1)____. A true friend stands by you when lessons are hard and cheers when you (2)____ well. I still remember how, in my first term, a classmate quietly (3)____ me his pen when I had forgotten mine. Such small kindnesses (4)____ a lot to a nervous newcomer. Over the years, my friends and I have (5)____ countless lunches, worries and dreams together. When I felt under (6)____ before an exam, they reminded me that I was good (7)____ just as I was. They never made nasty (8)____ when I made a mistake; instead they helped me learn from it. I have come to believe that a (9)____ smile from a friend can brighten the hardest day. Whatever happens, I know there will never be a (10)____ of kind people around me, and that thought gives me real comfort.', 148, 2, '[{"q":"1","answer":"A","options":["life","bell","gate","bus"],"explanation":"友谊是校园生活最珍贵的部分,school life。"},{"q":"2","answer":"B","options":["fall","do","lose","fail"],"explanation":"你做得好时为你欢呼,do well。"},{"q":"3","answer":"C","options":["sold","threw","lent","hid"],"explanation":"悄悄借给我笔,lent me his pen。"},{"q":"4","answer":"D","options":["cost","weigh","buy","mean"],"explanation":"小善举意义重大,mean a lot。"},{"q":"5","answer":"A","options":["shared","wasted","lost","sold"],"explanation":"一起分享许多午餐和梦想,shared。"},{"q":"6","answer":"B","options":["water","pressure","weather","music"],"explanation":"考试前承受压力,under pressure。"},{"q":"7","answer":"C","options":["later","alone","enough","away"],"explanation":"我本来就足够好,good enough。"},{"q":"8","answer":"D","options":["drinks","plans","gifts","comments"],"explanation":"从不刻薄评论,nasty comments。"},{"q":"9","answer":"A","options":["genuine","broken","empty","heavy"],"explanation":"朋友真诚的微笑,genuine smile。"},{"q":"10","answer":"B","options":["shower","shortage","crowd","list"],"explanation":"善良的人永远不会短缺,shortage of。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U1', 'A Word to New Students', 'If I could speak to next year''s first-year students, here is what I (1)____ tell them. Senior high is a new chapter, and you should step (2)____ into it with courage. Do not put too much (3)____ on yourself by trying to make every single day perfect. There is no such (4)____ as a perfect start; there is only good enough, and that is fine. You are not the only one who feels (5)____ — almost everyone around you feels the same way. When a lesson seems (6)____, ask a question instead of staying silent. When you meet someone who is not friendly, remember that their behaviour says more about (7)____ than about you. Most of all, keep an open mind and a (8)____ heart. Join a club, make a plan, and (9)____ a few good friends along the way. If you do these things, I am sure your first year will be far more (10)____ than you fear.', 159, 2, '[{"q":"1","answer":"C","options":["should","must","would","could"],"explanation":"过去将来语气表设想要说的话,I would tell them。"},{"q":"2","answer":"D","options":["back","down","away","forward"],"explanation":"勇敢迈进新篇章,step forward。"},{"q":"3","answer":"A","options":["pressure","paper","water","colour"],"explanation":"别给自己太多压力,too much pressure。"},{"q":"4","answer":"B","options":["place","thing","person","time"],"explanation":"没有完美这回事,no such thing。"},{"q":"5","answer":"C","options":["famous","rich","worried","tall"],"explanation":"你不是唯一感到担忧的人,feels worried。"},{"q":"6","answer":"D","options":["boring","cheap","lovely","confusing"],"explanation":"当一课令人困惑时,seems confusing。"},{"q":"7","answer":"A","options":["them","you","us","it"],"explanation":"他们的行为更说明他们自己,about them。"},{"q":"8","answer":"B","options":["cold","kind","heavy","empty"],"explanation":"保持善良的心,a kind heart。"},{"q":"9","answer":"C","options":["lose","drop","make","miss"],"explanation":"一路交几个好友,make friends。"},{"q":"10","answer":"D","options":["boring","silent","empty","pleasant"],"explanation":"第一年会比你担心的愉快得多,more pleasant。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·对话 Choosing a Club', '上外必修一 U1 · dialogue', 3, 'A: Hi Ben, have you decided which club to join this term?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·独白 Morning Announcement', '上外必修一 U1 · passage', 2, 'Good morning, everyone, and welcome to a new term. This is your head teacher speaking. First, the library will open half an hour earlier this term, so you can read or study before lessons begin. Second, all first-year students should pick up their timetables from the office today and check them carefully. Third, club sign-up starts this Friday; there are many clubs to choose from, so think about what you enjoy. Finally, remember that the first week may feel a little confusing, but your teachers are always here to help. If something is unclear, just ask. Have a wonderful term, and let''s make this a great year together.', '校长广播:欢迎新学期;图书馆本学期提前半小时开门,可在上课前阅读自习;高一新生今天到办公室领取课表并仔细核对;社团报名本周五开始,选择很多,想想自己的兴趣;开学第一周可能有点令人困惑,但老师随时帮忙,有不懂就问;祝大家学期愉快,一起把这一年过好。', 'uk_female', '[{"q":"Who is making the announcement?","type":"choice","answer":"D","options":["A first-year student.","The librarian.","A club leader.","The head teacher."]},{"q":"What change is made to the library this term?","type":"choice","answer":"A","options":["It opens half an hour earlier.","It closes for the whole term.","It moves to a new building.","It bans all first-year students."]},{"q":"What should first-year students do today?","type":"choice","answer":"B","options":["Sign up for clubs immediately.","Collect and check their timetables.","Clean the classrooms.","Take an English exam."]},{"q":"When does club sign-up begin?","type":"choice","answer":"C","options":["Next Monday.","Today after lunch.","This Friday.","At the end of term."]},{"q":"What does the head teacher say about the confusing first week?","type":"choice","answer":"D","options":["Students must solve everything alone.","It is best to stay home.","Nobody can do anything about it.","Teachers are always there to help, so just ask."]}]'::jsonb, '[]'::jsonb, 'short', 'required1', 'U1', 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·对话 Finding the Classroom', '上外必修一 U1 · dialogue', 3, 'A: Excuse me, could you help me? I can''t find my classroom.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·独白 My Study Plan', '上外必修一 U1 · passage', 2, 'When senior high started, I quickly learned that I had to be more independent than before. So I made a simple study plan to keep myself on track. Every evening I write down all my homework and tick off each task as I finish it. That way I always know which assignments are due and what I still have to get done. I also set up a quiet corner in my bedroom where I can concentrate without being disturbed. At first it was hard to keep the habit, but after a few weeks it felt natural. My grades have improved since I started planning, and I feel much less worried before deadlines. If you are a new student, I would really suggest making a plan of your own.', '高中开学后,我很快意识到要比以前更独立,于是制定了一个简单的学习计划。每晚我写下所有作业,完成一项就打个钩,这样总能知道哪些作业到期、还剩什么没做。我还在卧室布置了一个安静的角落,可以不受打扰地专心学习。一开始坚持很难,但几周后就成了习惯。自从开始做计划,我的成绩进步了,临近截止也不那么焦虑。如果你是新生,我真心建议你也定一个自己的计划。', 'uk_female', '[{"q":"What did the speaker realise when senior high started?","type":"choice","answer":"B","options":["She no longer needed to study.","She had to be more independent than before.","Homework would all disappear.","Teachers would do her work for her."]},{"q":"How does the speaker keep track of her homework?","type":"choice","answer":"C","options":["She tries to remember it all.","She asks a friend every night.","She writes it down and ticks off each finished task.","She only does it at weekends."]},{"q":"Why did she set up a quiet corner at home?","type":"choice","answer":"D","options":["So she could watch television.","So her friends could visit.","So she could sleep more.","So she could concentrate without being disturbed."]},{"q":"What happened after she started planning?","type":"choice","answer":"A","options":["Her grades improved and she felt less worried.","Her grades got worse.","She gave up all her plans.","She stopped doing homework."]},{"q":"What does the speaker suggest to new students?","type":"choice","answer":"B","options":["Avoiding all homework.","Making a study plan of their own.","Studying only in the library.","Copying her plan exactly."]}]'::jsonb, '[]'::jsonb, 'short', 'required1', 'U1', 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·对话 Interviewing a Newcomer', '上外必修一 U1 · dialogue', 3, 'A: Hi, I''m Li Mei from the school newspaper. Is anything exciting about your new school life?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·独白 A Mother''s Words', '上外必修一 U1 · passage', 2, 'Dear daughter, as you start senior high school, there are a few things I want you to remember. You may feel under pressure to make everything perfect, but there is no such thing as perfect — only good enough, and you already are. You are not alone; everyone around you is facing the same new school and new pressures. Some people may not always be friendly, but their unkind words say more about them than about you. There will never be a shortage of kind people and genuine smiles in your life. So go forward into this new chapter with courage, and don''t let the limits you put on yourself hold you back. I believe in you, and I always will.', '亲爱的女儿,在你开始高中生活之际,有几件事希望你记住。你也许会感到压力,想让一切都完美,但世上没有完美,只有“足够好”,而你已经足够好。你并不孤单,周围每个人都面对同样的新学校和新压力。有些人未必总是友善,但他们刻薄的话更说明他们自己,而非你。你的人生中善良的人和真诚的微笑永远不会短缺。所以鼓起勇气迈入人生新篇章,别让自己设下的局限阻碍你。我相信你,而且永远会相信。', 'uk_female', '[{"q":"Who is speaking in this passage?","type":"choice","answer":"D","options":["A teacher to a class.","A student to a friend.","A reporter to a newcomer.","A mother to her daughter."]},{"q":"What does the mother say about being perfect?","type":"choice","answer":"A","options":["There is no such thing as perfect; good enough is fine.","Her daughter must be perfect every day.","Only perfect students do well.","Perfection is easy to reach."]},{"q":"What does the mother say about unkind words from others?","type":"choice","answer":"B","options":["They are always true.","They say more about the speaker than about her daughter.","They should never be forgotten.","They mean her daughter has failed."]},{"q":"What does the mother say will never be in short supply?","type":"choice","answer":"C","options":["Difficult homework.","Strict school rules.","Kind people and genuine smiles.","Boring lessons."]},{"q":"What often holds people back, according to the mother?","type":"choice","answer":"D","options":["The size of the school.","The number of clubs.","The length of the term.","The limits they put on themselves."]}]'::jsonb, '[]'::jsonb, 'short', 'required1', 'U1', 'sufe');
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Describing My Ideal School Life(描述我理想的学校生活)', 'My Ideal School Life', '上外版必修一 Unit 1 写作任务。请用英语写一篇约100词的短文,描述你理想的学校生活,内容包括:① 理想的课程或学习方式;② 你想参加的校园活动或社团;③ 你希望拥有怎样的同学与师生关系;④ 这样的学校生活会给你怎样的感受。注意:用时态正确(现在/将来),句子地道、围绕中心。', 'Write a short passage of about 100 words describing your ideal school life. Include: 1) the courses or way of learning you would like; 2) the school activities or clubs you want to take part in; 3) what kind of classmates and teacher-student relationship you hope for; 4) how this school life would make you feel. Use tenses correctly (present / future) and keep every sentence on topic.', '["理想课程/学习方式(In my ideal school, lessons would be …)","想参加的活动/社团(I would join …)","理想的同学与师生关系(My classmates would be … and teachers would …)","这样的校园生活带来的感受(In such a school, I would feel …)"]'::jsonb, 70, 100, 'Everyone dreams of a perfect place to learn, and I often imagine my ideal school life. In my ideal school, lessons would be lively and creative, so that we could think freely instead of just memorising facts. After class, I would join a drama club and a reading group, where we share stories and perform on a real stage. My classmates would be kind and sympathetic, always ready to help one another, and our teachers would treat us as friends rather than judges. There would never be a shortage of warm smiles in the corridors. In such a school, I believe I would feel relaxed, confident and truly happy every single day.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["In my ideal school, lessons would be lively and creative, so that we could think freely.","I would join a drama club and a reading group, where we share stories and perform on a real stage.","My classmates would be kind and sympathetic, always ready to help one another.","There would never be a shortage of warm smiles in the corridors."]'::jsonb, '[{"wrong":"In my ideal school, lessons will be creative.","correct":"In my ideal school, lessons would be creative.","note":"描述想象/非真实情景,主句用 would,而非 will。"},{"wrong":"My classmates would helping each other.","correct":"My classmates would help each other.","note":"would 后接动词原形,不用 -ing。"},{"wrong":"There would never be a shortage of warm smile.","correct":"There would never be a shortage of warm smiles.","note":"a shortage of 后接可数名词复数 smiles。"}]'::jsonb, '【理想学校生活结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required1', 'U1', '{"title":"时态(复习 + 过去将来时)速查","intro":"选时态先找“时间信号”:时间状语(now / yesterday / since / by the time）和语境决定唯一答案。过去将来时是难点:站在过去某个时点往后看,用 would do 或 was/were going to do。","table":{"headers":["时态","标志 / 用法 / 例句"],"rows":[["一般现在","every day / usually / 客观事实:Our library opens early every weekday."],["现在进行","now / Look! / Listen! / at the moment:Listen! Someone is delivering a speech."],["一般过去","yesterday / last term / ago:Last term the teacher gave us an assignment."],["过去进行","at this time yesterday / when ...(从句一般过去):I was thinking about school at this time yesterday."],["现在完成","already / since / so far / for + 时间段:I have made three new friends so far."],["过去完成","by the time + 过去 / before + 过去(更早动作):By the time she arrived, the teacher had left."],["过去将来","said/hoped/thought + would do;过去的打算 = was/were going to do:He said he would beg the teacher."]]},"specialRules":[{"rule":"主句过去 → 宾语从句时态相应后移(现在→过去、将来→过去将来)","mark":"She said she WAS going to like it."},{"rule":"by the time + 一般过去,主句用过去完成(had done)","mark":"By last Friday we HAD chosen the topic."},{"rule":"since + 过去时间点 / 过去动作,主句用现在完成","mark":"Since the term began, I HAVE felt happier."},{"rule":"would do 与 was/were going to do 都表“过去将来”,后者更强调当时的打算","mark":"I was going to send you a message."}],"why":["时态的本质是“说话视角的时间点 + 动作相对它的先后/状态”;过去将来就是把视角放回过去,再往后看,所以 will→would、am going to→was going to。"],"gaokaoPoints":["语法填空高频:由 since / by the time / when 等连接词判断主从句时态搭配。","宾语从句时态呼应:主句过去时,从句须相应后移(would / had done / was doing)。","区分 had done(过去的过去)与 would do(过去将来)——看动作发生在“过去时点”之前还是之后。"],"examVsReal":[{"exam":"He said he would come.（考试用过去将来 would）","real":"He said he''ll come.","note":"口语里转述很近的将来常直接保留 will;考试默认时态呼应,用 would"},{"exam":"By the time I arrived, the class had started.（考试用 had done）","real":"When I got there, class already started.","note":"口语常用一般过去 + already 代替过去完成;书面/考试讲究 had done"}]}'::jsonb, 'sufe');
